#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_self_test_observation: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation>> = Mutex::new(None);
  pub static ref IN_test_cycle_directive: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::TestCycleDirective>> = Mutex::new(None);
  pub static ref OUT_cycle_assessment: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_self_test_observation.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_test_cycle_directive.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_cycle_assessment.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_self_test_observation(value: *mut Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation) -> bool
{
  unsafe {
    let guard = IN_self_test_observation.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_test_cycle_directive(value: *mut Vehicle_Start_Readiness_Recovery_Supervisor::TestCycleDirective) -> bool
{
  unsafe {
    let guard = IN_test_cycle_directive.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_cycle_assessment(value: *mut Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment) -> bool
{
  unsafe {
    *OUT_cycle_assessment.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
